#include <stdio.h>

int main() {
    /* 立即寻址：操作数直接编码在指令中 */
    int imm = 42;
    /* 直接寻址：操作数放在内存单元 3000，其值为 99 */
    int mem_3000 = 99;

    int result_imm = imm * 2;       /* 立即数参与运算，无需访存取数 */
    int result_dir = mem_3000 * 2;  /* 按 EA=3000 访存取数后再运算 */

    printf("立即寻址：指令内含操作数 %d，结果 = %d\n", imm, result_imm);
    printf("直接寻址：EA=3000 取数 %d，结果 = %d\n", mem_3000, result_dir);
    return 0;
}
